Q: SignalR and AzureAD authentication : loose websocket in favor of long polling A: <p>I got it working !
Even if I didn't get the OnMessageReceived to be called.</p>
<p>A modification was adding a service - likely to be closely equivalent to <strong><strong>AddAuthentication()</strong></strong> + <strong><strong>AddMicrosoftIdentityWeabApi()</strong></strong></p>
<pre><code>services.AddMicrosoftIdentityWebApiAuthentication(configuration, &quot;AzureAd&quot;);
</code></pre>
<p>And then add a custom middleware before <strong><strong>UseAuthentication()</strong></strong></p>
<pre><code>  app.UseMiddleware&lt;AccessTokenMiddleware&gt;();
  app.UseAuthentication();
</code></pre>
<p>The middleware puts the query string parameter in the headers</p>
<pre><code>public class AccessTokenMiddleware
{
  private readonly RequestDelegate next;
  public AccessTokenMiddleware(RequestDelegate next)
  {
    this.next = next;
  }
  public async Task Invoke(HttpContext httpContext)
  {
    var request = httpContext.Request;
    // Web sockets cannot pass headers so the access token must be taken from query param and
    // added to the header before authentication middleware runs
    if (request.Path.StartsWithSegments(SomeHub.Path, StringComparison.OrdinalIgnoreCase) &amp;&amp;
        request.Query.TryGetValue(&quot;access_token&quot;, out var accessToken))
      request.Headers.Add(&quot;Authorization&quot;, $&quot;Bearer {accessToken}&quot;);
    await next(httpContext);
  }
}
</code></pre>
